import path from "node:path";

import { eq, sql } from "drizzle-orm";
import { migrate } from "drizzle-orm/node-postgres/migrator";

import { getControlPlaneDb } from "@/db/control-plane/connection";
import { customers, type Customer } from "@/db/control-plane/schema";
import {
  assertCustomerDatabaseName,
  customerDatabaseName,
} from "@/db/customer/database-url";
import { closeCustomerPool, getCustomerDb } from "@/db/customer/pools";

/** Generated by `npm run db:generate:customer`. */
const CUSTOMER_MIGRATIONS_FOLDER = path.join(
  process.cwd(),
  "drizzle",
  "customer",
);

const ARCHIVED_PREFIX = "archived_";
const DUPLICATE_DATABASE = "42P04";

function pgErrorCode(error: unknown): string | undefined {
  for (let e: unknown = error; e instanceof Error; e = e.cause) {
    if ("code" in e && typeof e.code === "string") return e.code;
  }
  return undefined;
}

/** Quotes a database name for DDL. Only convention-following names get this far. */
function ident(databaseName: string): string {
  const live = databaseName.startsWith(ARCHIVED_PREFIX)
    ? databaseName.slice(ARCHIVED_PREFIX.length)
    : databaseName;
  assertCustomerDatabaseName(live);
  return `"${databaseName}"`;
}

async function databaseExists(databaseName: string): Promise<boolean> {
  const result = await getControlPlaneDb().execute(
    sql`select 1 from pg_database where datname = ${databaseName}`,
  );
  return result.rows.length > 0;
}

async function terminateConnections(databaseName: string): Promise<void> {
  await closeCustomerPool(databaseName);
  await getControlPlaneDb().execute(
    sql`select pg_terminate_backend(pid) from pg_stat_activity
        where datname = ${databaseName} and pid <> pg_backend_pid()`,
  );
}

/**
 * Brings a customer database up to the current customer schema. Applied
 * versions are tracked inside that database (`drizzle.__drizzle_migrations`),
 * so this is safe to run repeatedly — on provisioning and on upgrade.
 */
export async function migrateCustomerDatabase(
  databaseName: string,
): Promise<void> {
  await migrate(getCustomerDb(databaseName), {
    migrationsFolder: CUSTOMER_MIGRATIONS_FOLDER,
  });
}

/**
 * Creates (if needed) and migrates the dedicated database for a customer.
 * Idempotent. Returns the database name.
 */
export async function provisionCustomerDatabase(
  customerId: string,
): Promise<string> {
  const databaseName = customerDatabaseName(customerId);
  if (!(await databaseExists(databaseName))) {
    try {
      // CREATE DATABASE cannot run inside a transaction or take parameters.
      await getControlPlaneDb().execute(
        sql.raw(`create database ${ident(databaseName)}`),
      );
    } catch (error) {
      // A concurrent provision of the same customer got there first.
      if (pgErrorCode(error) !== DUPLICATE_DATABASE) throw error;
    }
  }
  await migrateCustomerDatabase(databaseName);
  return databaseName;
}

export interface CreateCustomerInput {
  organizationId: string;
  name: string;
}

/**
 * Creates a customer: provisions its database, then records it in the
 * control-plane registry. If the registry insert fails, the new (empty)
 * database is dropped again so nothing is left orphaned.
 */
export async function createCustomer(
  input: CreateCustomerInput,
): Promise<Customer> {
  const id = crypto.randomUUID();
  const databaseName = await provisionCustomerDatabase(id);
  try {
    const [customer] = await getControlPlaneDb()
      .insert(customers)
      .values({ id, databaseName, ...input })
      .returning();
    return customer;
  } catch (error) {
    await terminateConnections(databaseName);
    await getControlPlaneDb().execute(
      sql.raw(`drop database if exists ${ident(databaseName)}`),
    );
    throw error;
  }
}

/**
 * Archives a customer: marks it archived in the registry (so the resolver
 * refuses access) and renames its database to `archived_<name>`. The content
 * is kept. Idempotent.
 */
export async function archiveCustomerDatabase(
  customerId: string,
): Promise<void> {
  const databaseName = customerDatabaseName(customerId);
  await getControlPlaneDb()
    .update(customers)
    .set({ status: "archived" })
    .where(eq(customers.id, customerId));
  if (!(await databaseExists(databaseName))) return;
  await terminateConnections(databaseName);
  await getControlPlaneDb().execute(
    sql.raw(
      `alter database ${ident(databaseName)} rename to ${ident(ARCHIVED_PREFIX + databaseName)}`,
    ),
  );
}

/**
 * Reverses archiveCustomerDatabase: renames the database back and marks the
 * customer active again. Idempotent.
 */
export async function restoreCustomerDatabase(
  customerId: string,
): Promise<void> {
  const databaseName = customerDatabaseName(customerId);
  const archivedName = ARCHIVED_PREFIX + databaseName;
  if (await databaseExists(archivedName)) {
    await terminateConnections(archivedName);
    await getControlPlaneDb().execute(
      sql.raw(
        `alter database ${ident(archivedName)} rename to ${ident(databaseName)}`,
      ),
    );
  }
  await migrateCustomerDatabase(databaseName);
  await getControlPlaneDb()
    .update(customers)
    .set({ status: "active" })
    .where(eq(customers.id, customerId));
}

/**
 * PERMANENTLY deletes all of a customer's content (GDPR deletion): drops its
 * database, live or archived, and removes it from the registry.
 *
 * Safeguard: the caller must repeat the database name it expects to destroy;
 * a mismatch throws before anything is touched.
 */
export async function dropCustomerDatabase(
  customerId: string,
  confirmDatabaseName: string,
): Promise<void> {
  const databaseName = customerDatabaseName(customerId);
  if (confirmDatabaseName !== databaseName) {
    throw new Error(
      `Refusing to drop: confirmation "${confirmDatabaseName}" does not match "${databaseName}".`,
    );
  }
  for (const name of [databaseName, ARCHIVED_PREFIX + databaseName]) {
    await terminateConnections(name);
    await getControlPlaneDb().execute(
      sql.raw(`drop database if exists ${ident(name)}`),
    );
  }
  await getControlPlaneDb()
    .delete(customers)
    .where(eq(customers.id, customerId));
}
